from pysat.solvers import RC2
from pysat.formula import WCNF
from itertools import combinations

def solve():
    from pysat.solvers import Glucose3
    solver = Glucose3()

    # Variables: edge(i, j) for 0 <= i < j < 8
    def var(i, j):
        if i > j: i, j = j, i
        return i * 8 + j + 1

    # Degree exactly 4
    for i in range(8):
        edges = [var(i, j) for j in range(8) if i != j]
        # exactly 4
        from itertools import combinations
        # at least 4
        for c in combinations(edges, 8 - 4 + 1):
            solver.add_clause([e for e in c])
        # at most 4
        for c in combinations(edges, 4 + 1):
            solver.add_clause([-e for e in c])

    # Girth at least 4 (no triangles)
    for i in range(8):
        for j in range(i+1, 8):
            for k in range(j+1, 8):
                solver.add_clause([-var(i, j), -var(j, k), -var(i, k)])

    # Partial assignment
    solver.add_clause([var(0, 4)])
    solver.add_clause([var(0, 7)])
    solver.add_clause([var(2, 4)])

    if solver.solve():
        model = solver.get_model()
        edges = []
        for i in range(8):
            for j in range(i+1, 8):
                if model[var(i, j) - 1] > 0:
                    edges.append((i, j))
        print("SAT")
        print(edges)
    else:
        print("UNSAT")

solve()

