        return i * 8 + j + 1

    # Degree exactly 4
    for i in range(8):
        edges = [var(i, j) for j in range(8) if i != j]
        # exactly 4 out of 7
        # at least 4: cannot have 4 false
        for c in combinations(edges, 4):
            solver.add_clause([e for e in c])
        # at most 4: cannot have 5 true
        for c in combinations(edges, 5):
            solver.add_clause([-e for e in c])

    # Girth at least 4 (no triangles)
    for i in range(8):
        for j in range(i+1, 8):
            for k in range(j+1, 8):
