    # Partial assignment
    solver.add_clause([var(0, 4)])
    solver.add_clause([var(0, 7)])
    solver.add_clause([var(2, 4)])

    if solver.solve():
        model = solver.get_model()
        edges = []
        for i in range(8):
            for j in range(i+1, 8):
                if model[var(i, j) - 1] > 0:
